"""Split Array Largest Sum — binary search on the allowed subarray sum.

Counting the greedy number of chunks under a cap is linear, and the cap is
monotonic, so the smallest feasible cap is the answer.

Time: O(n log sum)   Space: O(1)
"""
from typing import List


class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        def chunks(cap: int) -> int:
            used, running = 1, 0
            for value in nums:
                if running + value > cap:
                    used += 1
                    running = 0
                running += value
            return used

        lo, hi = max(nums), sum(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if chunks(mid) <= k:
                hi = mid
            else:
                lo = mid + 1
        return lo
